1	/**
2	 * Private helpers shared by the service layer.
3	 *
4	 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
5	 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
6	 * Neither re-implements a cross-cutting concern — they are adapters onto
7	 * `@/lib/permissions` and `@/lib/event-bus`.
8	 */
9	import { toIsoTimestamp } from "@/types/common";
10	import type { Comment } from "@/types/comment";
11	import type { OrgId, UserId } from "@/types/common";
12	import type { EventEnvelope } from "@/types/event";
13	import type { Issue } from "@/types/issue";
14	import type { Actor, Member } from "@/types/member";
15	import type { PermissionResource } from "@/types/permission";
16	import type { Project } from "@/types/project";
17	import type { WebhookId } from "@/types/common";
18	
19	/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
20	export class NotFoundError extends Error {
21	  readonly code = "not_found" as const;
22	
23	  constructor(
24	    readonly entity: string,
25	    readonly id: string,
26	  ) {
27	    super(`${entity} ${id} was not found`);
28	    this.name = "NotFoundError";
29	  }
30	}
31	
32	/** Unwraps a repository read, turning the `null` case into a domain error. */
33	export function requireFound<T>(
34	  value: T | null | undefined,
35	  entity: string,
36	  id: string,
37	): T {
38	  if (value === null || value === undefined) {
39	    throw new NotFoundError(entity, id);
40	  }
41	  return value;
42	}
43	
44	export function orgResource(orgId: OrgId): PermissionResource {
45	  return { kind: "organization", orgId };
46	}
47	
48	export function billingResource(orgId: OrgId): PermissionResource {
49	  return { kind: "billing", orgId };
50	}
51	
52	export function activityResource(orgId: OrgId): PermissionResource {
53	  return { kind: "activity", orgId };
54	}
55	
56	export function notificationResource(
57	  orgId: OrgId,
58	  recipientId: UserId,
59	): PermissionResource {
60	  return { kind: "notification", orgId, recipientId };
61	}
62	
63	export function webhookResource(
64	  orgId: OrgId,
65	  webhookId: WebhookId | null,
66	): PermissionResource {
67	  return { kind: "webhook", orgId, webhookId };
68	}
69	
70	export function memberResource(member: Member): PermissionResource {
71	  return {
72	    kind: "member",
73	    orgId: member.orgId,
74	    memberId: member.id,
75	    targetUserId: member.userId,
76	    targetRole: member.role,
77	  };
78	}
79	
80	export function projectResource(project: Project): PermissionResource {
81	  return {
82	    kind: "project",
83	    orgId: project.orgId,
84	    projectId: project.id,
85	    visibility: project.visibility,
86	    leadId: project.leadId,
87	  };
88	}
89	
90	export function issueResource(issue: Issue): PermissionResource {
91	  return {
92	    kind: "issue",
93	    orgId: issue.orgId,
94	    projectId: issue.projectId,
95	    issueId: issue.id,
96	    authorId: issue.authorId,
97	    assigneeId: issue.assigneeId,
98	  };
99	}
100	
101	export function commentResource(comment: Comment): PermissionResource {
102	  return {
103	    kind: "comment",
104	    orgId: comment.orgId,
105	    commentId: comment.id,
106	    authorId: comment.authorId,
107	  };
108	}
109	
110	/** The three fields the bus stamps on every payload. */
111	export function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {
112	  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };
113	}
114	
115	/** Same envelope, taken from an `Actor` rather than assembled by hand. */
116	export function actorEnvelope(actor: Actor): EventEnvelope {
117	  return envelope(actor.orgId, actor.userId);
118	}
119	
120	/** Names the fields an update actually changed, for `issue.updated`. */
121	export function changedFields<T extends object>(
122	  before: T,
123	  after: T,
124	): readonly string[] {
125	  return Object.keys(after).filter(
126	    (key) =>
127	      JSON.stringify(before[key as keyof T]) !==
128	      JSON.stringify(after[key as keyof T]),
129	  );
130	}
131

