/** Setting or clearing your own absence is always allowed; anyone else's requires the role-change permission. */
function assertCanManageAbsence(actor: Actor, member: Member): void {
  if (actor.userId === member.userId) return;
  assertCan(actor, "member:update_role", memberResource(member));
}

/**
 * Stores `input` as the member's absence, replacing whatever was set before.
 * Both the member and, when given, the delegate must be active members of the
 * workspace, the delegate may not be the member themselves, and the window
 * must be non-empty.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const member = await requireActiveMember(input.orgId, input.userId);
  assertCanManageAbsence(actor, member);

  if (new Date(input.endsAt).getTime() <= new Date(input.startsAt).getTime()) {
    throw new Error("An absence must end after it starts");
  }

  if (input.delegateUserId !== null) {
    if (input.delegateUserId === input.userId) {
      throw new Error("A member cannot delegate to themselves");
    }
    await requireActiveMember(input.orgId, input.delegateUserId);
  }

  return memberAbsenceRepo.upsertAbsence(input);
}

/** Clearing an absence that was never set is a no-op, not an error. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  assertCanManageAbsence(actor, member);

  await memberAbsenceRepo.deleteAbsence(orgId, userId);
}

/**
 * The stored absence, or `null` once it has ended (or none was set). A
 * scheduled absence that has not started yet is still returned.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  await requireActiveMember(orgId, userId);

  const absence = await memberAbsenceRepo.findAbsence(orgId, userId);
  if (!absence) return null;

  return new Date(absence.endsAt).getTime() > Date.now() ? absence : null;
}

/**
 * The delegate that assignments and alerts for `userId` should be redirected
 * to right now, or `null` when `userId` is not currently away or has no
 * delegate. Redirection is a single hop — a delegate's own absence, if any,
 * is never consulted here.
 */
export async function resolveDelegate(
  orgId: OrgId,
  userId: UserId,
  at: Date = new Date(),
): Promise<UserId | null> {
  const absence = await memberAbsenceRepo.findAbsence(orgId, userId);
  if (!absence || absence.delegateUserId === null) return null;

  const now = at.getTime();
  const startsAt = new Date(absence.startsAt).getTime();
  const endsAt = new Date(absence.endsAt).getTime();

  return now >= startsAt && now < endsAt ? absence.delegateUserId : null;
}

