  it("getAbsence: returns scheduled, hides ended, null when unset", async () => {
    expect(
      await memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.admin),
    ).toBeNull();

    const scheduled = await memberService.setAbsence(tenant.actors.owner, {
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      delegateUserId: null,
      startsAt: iso(500000) as never,
      endsAt: iso(600000) as never,
      note: null,
    });
    const read = await memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);
    expect(read).toMatchObject({ startsAt: scheduled.startsAt });

    await memberService.setAbsence(tenant.actors.owner, {
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      delegateUserId: null,
      startsAt: iso(-100000) as never,
      endsAt: iso(-1000) as never,
      note: null,
    });
    expect(
      await memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.admin),
    ).toBeNull();

    await memberService.clearAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);
  });

  it("redirects a new assignment to the delegate, alerts the delegate not the absent member", async () => {
    await memberService.setAbsence(tenant.actors.owner, {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: iso(-1000) as never,
      endsAt: iso(100000) as never,
      note: null,
    });

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Away redirect",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.admin);

    const reassigned = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });
    expect(reassigned.assigneeId).toBe(tenant.userIds.admin);

    const adminNotifs = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["issue_assigned"],
      limit: 25,
      cursor: null,
    });
    expect(adminNotifs.items.length).toBeGreaterThanOrEqual(1);

    const memberNotifs = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      kind: ["issue_assigned"],
      limit: 25,
      cursor: null,
    });
    expect(memberNotifs.items).toHaveLength(0);

    // Self-assignment is never redirected, even while away.
    const selfAssigned = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });
    expect(selfAssigned.assigneeId).toBe(tenant.userIds.member);

    await memberService.clearAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member);
  });

