  it("drops the absence and any delegation when the member is removed", async () => {
    const t = await createTenant("absencesmoke-remove", "growth");
    await memberService.setAbsence(t.actors.owner, {
      orgId: t.org.id,
      userId: t.userIds.member,
      delegateUserId: t.userIds.admin,
      startsAt: iso(-1000) as never,
      endsAt: iso(100000) as never,
      note: null,
    });

    const adminMember = await memberRepo.findMember(t.org.id, t.userIds.admin);
    if (!adminMember) throw new Error("fixture admin missing");
    await memberService.removeMember(t.actors.owner, {
      orgId: t.org.id,
      memberId: adminMember.id,
    });

    const stillThere = await memberService.getAbsence(t.actors.owner, t.org.id, t.userIds.member);
    expect(stillThere).not.toBeNull();
    expect(stillThere?.delegateUserId).toBeNull();

    const memberRow = await memberRepo.findMember(t.org.id, t.userIds.member);
    if (!memberRow) throw new Error("fixture member missing");
    await memberService.removeMember(t.actors.owner, {
      orgId: t.org.id,
      memberId: memberRow.id,
    });

    await expect(
      memberService.getAbsence(t.actors.owner, t.org.id, t.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
